-- Demo catalogue seed: 5 categories, 24 products, 89 images, 321 variants.
-- Generated from src/mocks/data/*.ts. Idempotent: safe to re-run after 0001_schema.sql and the 0003_* migrations.
-- Apply in the Supabase SQL editor or with: supabase db query --file supabase/seed.sql
insert into public.categories (slug, name, description, image_url, sort_order, intro_title, intro_body)
select c.slug, c.name, c.description, c.image_url, c.sort_order, c.intro_title, c.intro_body from jsonb_to_recordset($j$[{"slug":"clogs","name":"Clogs","description":"Moulded EVA clogs with a removable heel strap, made in Marikina for Manila streets.","image_url":"https://images.pexels.com/photos/18368104/pexels-photo-18368104.jpeg?auto=compress&cs=tinysrgb&w=900","sort_order":1,"intro_title":"Clogs that take the heat.","intro_body":"Our clogs are injection-moulded from a single piece of lightweight EVA foam, so there are no seams to split and nothing to soak up rain. Pop the strap behind the heel for errands, flip it over the top for slip-on days. Every colourway is **washable** and dries in minutes."},{"slug":"slides","name":"Slides","description":"Cushioned one- and two-strap slides with a non-slip sole for pool, pavement and sari-sari runs.","image_url":"https://images.pexels.com/photos/18186215/pexels-photo-18186215.jpeg?auto=compress&cs=tinysrgb&w=900","sort_order":2,"intro_title":"Slides for the city heat.","intro_body":"Thick EVA footbeds with a moulded arch, wide adjustable straps and a sole that grips wet tile. Slip them on and forget about them."},{"slug":"loafer-mules","name":"Loafer Mules","description":"Closed-toe mules with a loafer silhouette: office-ready uppers on the same cushioned clog sole.","image_url":"https://images.pexels.com/photos/10117809/pexels-photo-10117809.jpeg?auto=compress&cs=tinysrgb&w=900","sort_order":3,"intro_title":"Dressed-up comfort.","intro_body":"The loafer mule puts a cleaner, closed-toe upper on our cushioned sole. Backless so you can kick them off under the desk, structured enough for a client meeting."},{"slug":"straps-accessories","name":"Straps & Accessories","description":"Replacement straps, charms and care kits to refresh a pair you already own.","image_url":"https://images.pexels.com/photos/37290957/pexels-photo-37290957.jpeg?auto=compress&cs=tinysrgb&w=900","sort_order":4,"intro_title":"Make them yours.","intro_body":"Swap the heel strap for a new colour, add a charm pack, or bring a well-loved pair back to life with the care kit. Straps are sized to match your clog size."},{"slug":"kids","name":"Kids","description":"Mini clogs and slides in kids sizes 5–8, with a snug heel strap for the playground.","image_url":"https://images.pexels.com/photos/37305529/pexels-photo-37305529.jpeg?auto=compress&cs=tinysrgb&w=900","sort_order":5,"intro_title":"Small feet, same sole.","intro_body":"The same washable EVA as the grown-up range, scaled down with a secure heel strap. Kids styles use our kids size run (5–8); measure foot length and use the size guide."}]$j$::jsonb) as c(slug text, name text, description text, image_url text, sort_order int, intro_title text, intro_body text)
on conflict (slug) do update set name = excluded.name, description = excluded.description, image_url = excluded.image_url, sort_order = excluded.sort_order, intro_title = excluded.intro_title, intro_body = excluded.intro_body;
insert into public.products (slug, name, description, details, category_id, base_price, sale_price, status, is_featured, sales_count, created_at)
select p.slug, p.name, p.description, (select coalesce(array_agg(d), '{}') from jsonb_array_elements_text(p.details) d), c.id, p.base_price, p.sale_price, p.status::public.product_status, p.is_featured, p.sales_count, p.created_at::timestamptz from jsonb_to_recordset($j$[{"slug":"lava-premium-clog","name":"Lava Premium Clog","description":"Our signature clog in a deep volcanic red. Injection-moulded from a single piece of lightweight EVA foam with a roomy toe box, a contoured arch and a removable heel strap you can wear back or flipped forward.","details":["Single-piece EVA foam, 220 g per pair (size 8)","Runs true to size; size up if you wear them with socks","Removable heel strap with matte rivets","Ventilation ports drain water in seconds","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1190,"sale_price":null,"status":"published","is_featured":true,"sales_count":412,"created_at":"2026-06-16T02:35:51.857Z"},{"slug":"ice-premium-clog","name":"Ice Premium Clog","description":"The Premium Clog in a cool, pale blue that reads almost white in the sun. Same cushioned footbed, same removable strap, with a tonal strap rivet.","details":["Single-piece EVA foam","Runs true to size; size up if you wear them with socks","Removable heel strap, tonal rivets","Non-slip tread pattern","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1190,"sale_price":null,"status":"published","is_featured":false,"sales_count":64,"created_at":"2026-10-02T02:35:51.857Z"},{"slug":"midnight-clog","name":"Midnight Clog","description":"A near-black navy clog that hides scuffs and goes with everything. Slightly firmer EVA compound for people who stand all day, with the same removable strap.","details":["Firm-density EVA foam","Runs true to size; size up if you wear them with socks","Removable heel strap","Odour-resistant footbed","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1090,"sale_price":890,"status":"published","is_featured":false,"sales_count":150,"created_at":"2026-07-11T02:35:51.857Z"},{"slug":"forest-camo-clog","name":"Forest Camo Clog","description":"A hydro-dipped woodland camo over our Forest base. Every pair takes the print slightly differently, so no two are identical. Removable strap in solid Forest.","details":["Single-piece EVA foam with hydro-dip print","Runs true to size; size up if you wear them with socks","Removable heel strap","Print is sealed and will not peel in the wash","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1390,"sale_price":null,"status":"published","is_featured":false,"sales_count":30,"created_at":"2026-10-09T02:35:51.857Z"},{"slug":"soft-tone-clog-sand","name":"Soft Tone Clog – Sand","description":"From the Soft Tones drop: muted, chalky colourways that pair with linen and denim alike. The Sand base ships with a Bone strap for a two-tone look; swap in any strap from the accessories range.","details":["Single-piece EVA foam, matte finish","Runs true to size; size up if you wear them with socks","Two-tone removable heel strap","Contoured arch support","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1290,"sale_price":null,"status":"published","is_featured":true,"sales_count":230,"created_at":"2026-05-17T02:35:51.857Z"},{"slug":"soft-tone-clog-sage","name":"Soft Tone Clog – Sage","description":"The Soft Tones clog in a dusty green with a Lilac strap. Matte EVA that resists scuffing, with the same cushioned footbed as the Premium Clog.","details":["Single-piece EVA foam, matte finish","Runs true to size; size up if you wear them with socks","Two-tone removable heel strap","Ventilation ports","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1290,"sale_price":null,"status":"published","is_featured":false,"sales_count":98,"created_at":"2026-07-26T02:35:51.857Z"},{"slug":"evil-eye-charm-clog","name":"Evil Eye Charm Clog","description":"The Premium Clog pre-loaded with a set of six evil-eye charms in blue, white and gold enamel. Charms pop in and out of the ventilation ports so you can rearrange them.","details":["Single-piece EVA foam","Runs true to size; size up if you wear them with socks","Includes 6 enamel charms","Removable heel strap","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1490,"sale_price":1190,"status":"published","is_featured":false,"sales_count":140,"created_at":"2026-06-26T02:35:51.857Z"},{"slug":"fleece-lined-clog","name":"Fleece-Lined Clog","description":"A closed-port clog with a removable brushed-fleece liner for Baguio weekends and over-chilled offices. Liner washes separately; the shell is the same EVA as the rest of the range.","details":["Closed-port EVA shell with removable fleece liner","Runs true to size with the liner in; size down without it","Removable heel strap","Machine wash the liner cold; rinse the shell"],"cat":"clogs","base_price":1690,"sale_price":null,"status":"draft","is_featured":false,"sales_count":0,"created_at":"2026-10-11T02:35:51.857Z"},{"slug":"platform-clog","name":"Platform Clog","description":"An extra 2.5 cm of EVA under the Premium Clog. Same weight class thanks to a lower-density core, with a wider outsole for stability and the removable strap.","details":["Dual-density EVA foam, 4.5 cm total stack","Runs true to size; size up if you wear them with socks","Removable heel strap","Wide-base non-slip outsole","Rinse with soap and water, air dry away from direct sun"],"cat":"clogs","base_price":1590,"sale_price":null,"status":"published","is_featured":true,"sales_count":280,"created_at":"2026-06-06T02:35:51.857Z"},{"slug":"island-two-strap-slide","name":"Island Two-Strap Slide","description":"Two wide, adjustable straps on a thick contoured footbed. Built for island hopping: the sole grips wet boat decks and the whole thing rinses clean of sand.","details":["EVA footbed with moulded arch, 3 cm heel","Two adjustable hook-and-loop straps","Runs true to size; size up if you wear them with socks","Non-slip wet-grip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"slides","base_price":990,"sale_price":null,"status":"published","is_featured":true,"sales_count":45,"created_at":"2026-09-24T02:35:51.857Z"},{"slug":"court-slide","name":"Court Slide","description":"A classic single-band slide with a debossed logo and a softer footbed than the clogs. The everyday pair for condos, gyms and quick runs to the sari-sari.","details":["Soft EVA footbed","Single moulded band","Runs true to size; size up if you wear them with socks","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"slides","base_price":890,"sale_price":null,"status":"published","is_featured":false,"sales_count":72,"created_at":"2026-08-05T02:35:51.857Z"},{"slug":"cloud-slide","name":"Cloud Slide","description":"Our softest footbed, a pillowy low-density EVA that compresses underfoot and springs back. A wide single strap keeps it secure without pressure points.","details":["Low-density EVA, 4 cm stack","Wide single strap","Runs half a size large; size down if between sizes","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"slides","base_price":1190,"sale_price":890,"status":"published","is_featured":false,"sales_count":95,"created_at":"2026-07-06T02:35:51.857Z"},{"slug":"crossover-slide","name":"Crossover Slide","description":"Two straps that cross over the instep for a more secure hold than a single band. A slightly firmer footbed suits long walking days.","details":["Medium-density EVA footbed","Crossed moulded straps","Runs true to size; size up if you wear them with socks","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"slides","base_price":1090,"sale_price":null,"status":"published","is_featured":true,"sales_count":160,"created_at":"2026-05-27T02:35:51.857Z"},{"slug":"recovery-slide","name":"Recovery Slide","description":"A deep-cradle footbed with a pronounced arch and a raised heel cup, designed for the day after a long run or a long shift on your feet.","details":["Dual-density EVA with deep heel cup","Single adjustable strap","Runs true to size; size up if you wear them with socks","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"slides","base_price":1290,"sale_price":null,"status":"published","is_featured":false,"sales_count":58,"created_at":"2026-08-15T02:35:51.857Z"},{"slug":"terra-loafer-mule","name":"Terra Loafer Mule","description":"A closed-toe, backless loafer silhouette moulded in matte EVA. Office-appropriate from the front, slip-on easy from the back, and still fully washable.","details":["Matte EVA upper and footbed","Runs true to size; size up if you wear them with socks","Backless loafer cut","Contoured arch support","Rinse with soap and water, air dry away from direct sun"],"cat":"loafer-mules","base_price":1890,"sale_price":null,"status":"published","is_featured":false,"sales_count":20,"created_at":"2026-10-05T02:35:51.857Z"},{"slug":"studio-loafer-mule","name":"Studio Loafer Mule","description":"The first-run loafer mule with a squared toe and a thinner sole. Replaced by the Terra and Dusk, kept here for anyone who wants to re-order their pair.","details":["Matte EVA upper and footbed","Runs true to size; size up if you wear them with socks","Squared toe","Rinse with soap and water, air dry away from direct sun"],"cat":"loafer-mules","base_price":1990,"sale_price":null,"status":"archived","is_featured":false,"sales_count":40,"created_at":"2026-03-28T02:35:51.857Z"},{"slug":"dusk-loafer-mule","name":"Dusk Loafer Mule","description":"Our dressiest shape: a loafer mule with a moulded penny strap detail and a slightly tapered toe. Cushioned like a clog, finished like a shoe.","details":["Matte EVA upper with moulded penny strap","Runs true to size; size up if you wear them with socks","Backless loafer cut","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"loafer-mules","base_price":2490,"sale_price":null,"status":"published","is_featured":true,"sales_count":190,"created_at":"2026-05-07T02:35:51.857Z"},{"slug":"replacement-strap-set","name":"Replacement Strap Set","description":"A pair of heel straps with rivets, sized to match your clog. Swap colours to refresh a pair or replace a strap that has gone missing.","details":["Moulded EVA strap, two rivets per pair","Order the same size as your clog","Fits every clog in the range","Rinse with soap and water, air dry away from direct sun"],"cat":"straps-accessories","base_price":390,"sale_price":null,"status":"published","is_featured":false,"sales_count":310,"created_at":"2026-07-21T02:35:51.857Z"},{"slug":"sole-charm-pack","name":"Sole Charm Pack","description":"Eight enamel charms — sun, jeepney, mango, wave and friends — that push into the ventilation ports of any clog. One size fits every pair; select 8 at checkout.","details":["8 enamel charms with rubber backs","One size (listed as 8)","Fits all clog ventilation ports","Wipe clean"],"cat":"straps-accessories","base_price":290,"sale_price":null,"status":"published","is_featured":false,"sales_count":42,"created_at":"2026-09-19T02:35:51.857Z"},{"slug":"sport-heel-strap","name":"Sport Heel Strap","description":"An elasticated heel strap with a hook-and-loop closure that locks a clog on for cycling, commuting and chasing kids. Swaps onto the standard rivets in seconds.","details":["Elastic webbing with hook-and-loop closure","Order the same size as your clog","Fits every clog in the range","Hand wash"],"cat":"straps-accessories","base_price":490,"sale_price":390,"status":"published","is_featured":false,"sales_count":80,"created_at":"2026-07-01T02:35:51.857Z"},{"slug":"clog-care-kit","name":"Clog Care Kit","description":"A soft brush, a scuff eraser and a bottle of EVA-safe cleaner to bring a well-loved pair back to new. Retired while we reformulate the cleaner.","details":["Brush, eraser and 120 ml cleaner","One size (listed as 8)","Safe on all colourways"],"cat":"straps-accessories","base_price":590,"sale_price":null,"status":"archived","is_featured":false,"sales_count":73,"created_at":"2026-04-17T02:35:51.857Z"},{"slug":"kids-mini-clog","name":"Kids Mini Clog","description":"The Premium Clog scaled down for small feet, with a snugger heel strap that stays put on the playground. Kids sizes 5–8 (our kids run, not US adult sizing); measure foot length and use the size guide.","details":["Single-piece EVA foam","Kids run 5–8; size up if between sizes","Snug-fit heel strap","Non-slip tread","Rinse with soap and water, air dry away from direct sun"],"cat":"kids","base_price":890,"sale_price":null,"status":"published","is_featured":false,"sales_count":75,"created_at":"2026-09-16T02:35:51.857Z"},{"slug":"kids-forest-camo-clog","name":"Kids Forest Camo Clog","description":"The hydro-dipped camo clog in kids sizes 5–8, with a solid Forest heel strap. Each pair takes the print a little differently.","details":["Single-piece EVA foam with hydro-dip print","Kids run 5–8; size up if between sizes","Snug-fit heel strap","Rinse with soap and water, air dry away from direct sun"],"cat":"kids","base_price":990,"sale_price":null,"status":"published","is_featured":false,"sales_count":30,"created_at":"2026-09-29T02:35:51.857Z"},{"slug":"kids-two-strap-slide","name":"Kids Two-Strap Slide","description":"The Island Two-Strap Slide in kids sizes 5–8 with shorter, grippier straps and a brighter strap rivet. Launching with the next drop.","details":["EVA footbed with moulded arch","Kids run 5–8","Two adjustable hook-and-loop straps","Rinse with soap and water, air dry away from direct sun"],"cat":"kids","base_price":890,"sale_price":null,"status":"draft","is_featured":false,"sales_count":0,"created_at":"2026-10-12T02:35:51.857Z"}]$j$::jsonb) as p(slug text, name text, description text, details jsonb, cat text, base_price numeric, sale_price numeric, status text, is_featured boolean, sales_count int, created_at text) join public.categories c on c.slug = p.cat
on conflict (slug) do update set name = excluded.name, description = excluded.description, details = excluded.details, category_id = excluded.category_id, base_price = excluded.base_price, sale_price = excluded.sale_price, status = excluded.status, is_featured = excluded.is_featured;
delete from public.product_images where product_id in (select id from public.products where slug in ('lava-premium-clog','ice-premium-clog','midnight-clog','forest-camo-clog','soft-tone-clog-sand','soft-tone-clog-sage','evil-eye-charm-clog','fleece-lined-clog','platform-clog','island-two-strap-slide','court-slide','cloud-slide','crossover-slide','recovery-slide','terra-loafer-mule','studio-loafer-mule','dusk-loafer-mule','replacement-strap-set','sole-charm-pack','sport-heel-strap','clog-care-kit','kids-mini-clog','kids-forest-camo-clog','kids-two-strap-slide'));
insert into public.product_images (product_id, url, alt, is_primary, sort_order)
select pr.id, 'https://images.pexels.com/photos/' || i.pid || '/pexels-photo-' || i.pid || '.jpeg?auto=compress&cs=tinysrgb&w=900', g.name || ' - ' || (array['side view','detail','top view','on foot','view'])[i.ord], i.ord = 1, i.ord - 1 from jsonb_to_recordset($j$[{"slug":"lava-premium-clog","name":"Lava Premium Clog","ids":["18368104","18368096","12320132","12349148"]},{"slug":"ice-premium-clog","name":"Ice Premium Clog","ids":["9313792","12120326","12189411","10410066"]},{"slug":"midnight-clog","name":"Midnight Clog","ids":["12616156","1689612","18255352","18255346"]},{"slug":"forest-camo-clog","name":"Forest Camo Clog","ids":["1033774","39048466","25306342"]},{"slug":"soft-tone-clog-sand","name":"Soft Tone Clog – Sand","ids":["18188524","18188523","12922455"]},{"slug":"soft-tone-clog-sage","name":"Soft Tone Clog – Sage","ids":["18188523","12922455","18188548"]},{"slug":"evil-eye-charm-clog","name":"Evil Eye Charm Clog","ids":["13097398","18255347","28211248","10078139"]},{"slug":"fleece-lined-clog","name":"Fleece-Lined Clog","ids":["18255352","18255346","24509391"]},{"slug":"platform-clog","name":"Platform Clog","ids":["25906614","8801134","8801123","8801175"]},{"slug":"island-two-strap-slide","name":"Island Two-Strap Slide","ids":["31129829","4296072","37305536","38621731","9074406"]},{"slug":"court-slide","name":"Court Slide","ids":["18186215","26585906","10596762","13698233"]},{"slug":"cloud-slide","name":"Cloud Slide","ids":["24645252","24645253","24645250","13966800"]},{"slug":"crossover-slide","name":"Crossover Slide","ids":["13966799","13836590","11883902","38755593","33987673"]},{"slug":"recovery-slide","name":"Recovery Slide","ids":["30471939","29320435","9741975","12368093","9741912"]},{"slug":"terra-loafer-mule","name":"Terra Loafer Mule","ids":["10117809","10117818"]},{"slug":"studio-loafer-mule","name":"Studio Loafer Mule","ids":["7691385","7691393","5059657"]},{"slug":"dusk-loafer-mule","name":"Dusk Loafer Mule","ids":["21555668","13066629","1687821"]},{"slug":"replacement-strap-set","name":"Replacement Strap Set","ids":["8989596","36937550","31129829","37305536"]},{"slug":"sole-charm-pack","name":"Sole Charm Pack","ids":["37290957","36550153","28211248","10078139"]},{"slug":"sport-heel-strap","name":"Sport Heel Strap","ids":["18255347","12120326","18368096"]},{"slug":"clog-care-kit","name":"Clog Care Kit","ids":["12189411","12349148","8223777","12262095"]},{"slug":"kids-mini-clog","name":"Kids Mini Clog","ids":["37305529","37305530","37305528","18255347"]},{"slug":"kids-forest-camo-clog","name":"Kids Forest Camo Clog","ids":["37242420","4671991","39772270","10078139"]},{"slug":"kids-two-strap-slide","name":"Kids Two-Strap Slide","ids":["8084238","37305536","37290957"]}]$j$::jsonb) as g(slug text, name text, ids jsonb) join public.products pr on pr.slug = g.slug cross join lateral jsonb_array_elements_text(g.ids) with ordinality as i(pid, ord);
